/// Write-side GitLab issues tracker client — Java `GitLabTrackerClient` /
/// `GitLabTicket` parity (epam/dm.ai#876).
///
/// Java injects a `TrackerClient` into jobs (`DEFAULT_TRACKER=gitlab` via
/// `TrackerModule`); the Dart runtime's tracker surface is the `gitlab_*`
/// sync tool catalog, so this client routes over it through a
/// [SyncToolExecute] dispatcher — the same pattern [GithubTrackerClient]
/// uses. Operations map 1:1 onto the Java tracker client:
///
/// | Java                       | Dart / tool                        |
/// |----------------------------|------------------------------------|
/// | `postComment`              | `gitlab_create_issue_comment`      |
/// | `moveToStatus`             | `gitlab_move_issue_to_status`      |
/// | `assignTo`                 | `gitlab_assign_issue`              |
/// | `addLabelIfNotExists`      | `gitlab_add_issue_label`           |
/// | `deleteLabelInTicket`      | `gitlab_remove_issue_label`        |
/// | `createTicketInProject`    | `gitlab_create_issue`              |
///
/// Tickets are keyed `namespace/project#iid` (Java `GitLabTicket
/// .getTicketKey()` composite). `gl-<n>` and a bare IID resolve against the
/// configured default project (`GITLAB_WORKSPACE` / `GITLAB_REPOSITORY`, or
/// the CI-provided `CI_PROJECT_PATH`). Failures surface as [StateError] —
/// Java's `IOException` parity.
library;

import '../config/property_reader.dart';
import '../config/property_reader_getters.dart';
import 'github_tracker_client.dart'
    show
        SyncToolExecute,
        defaultTrackerExecute,
        trackerErrorOf,
        trackerTryDecode;

/// A resolved `(projectPath, iid)` GitLab issue reference.
typedef GitlabTrackerIssueRef = (String projectPath, String iid);

/// Write-side tracker operations backed by GitLab project issues.
class GitlabTrackerClient {
  /// Creates the client; [execute] defaults to the real sync dispatcher.
  GitlabTrackerClient({SyncToolExecute? execute})
      : _execute = execute ?? defaultTrackerExecute;

  final SyncToolExecute _execute;

  /// Whether GitLab tracker operations can run (`GITLAB_TOKEN` present —
  /// Java `getInstance()` returns null without it).
  bool get isConfigured => (PropertyReader().getGitLabToken() ?? '').isNotEmpty;

  /// Posts a comment to the issue [key] refers to (Java `postComment`).
  void postComment(String key, String body) =>
      _dispatchKeyed(key, 'gitlab_create_issue_comment', {'body': body});

  /// Moves the issue to [status] — done/closed/completed/resolved close it,
  /// open/reopened reopen it, anything else lands as `status::<status>`
  /// (Java `moveToStatus`).
  void moveToStatus(String key, String status) => _dispatchKeyed(
      key, 'gitlab_move_issue_to_status', {'statusName': status});

  /// Assigns the issue to [user] (Java `assignTo`).
  void assignTo(String key, String user) =>
      _dispatchKeyed(key, 'gitlab_assign_issue', {'user': user});

  /// Adds [label] to the issue (Java `addLabelIfNotExists`).
  void addLabel(String key, String label) =>
      _dispatchKeyed(key, 'gitlab_add_issue_label', {'label': label});

  /// Removes [label] from the issue (Java `deleteLabelInTicket`).
  void removeLabel(String key, String label) =>
      _dispatchKeyed(key, 'gitlab_remove_issue_label', {'label': label});

  /// Creates an issue in [project] (`namespace/project`) and returns the
  /// composite key `namespace/project#<iid>` (Java `createTicketInProject`
  /// → `GitLabTicket.getTicketKey()`).
  String createTicket({
    required String project,
    required String summary,
    String description = '',
  }) {
    final trimmedProject = project.trim();
    if (!trimmedProject.contains('/') ||
        trimmedProject.split('/').any((p) => p.trim().isEmpty)) {
      throw StateError(
        "createTicket needs a 'namespace/project' project, got: '$project'",
      );
    }
    final raw = _execute('gitlab_create_issue', {
      'key': trimmedProject,
      'title': summary,
      if (description.isNotEmpty) 'body': description,
    });
    final decoded = raw == null ? null : trackerTryDecode(raw);
    final iid = decoded is Map ? decoded['iid'] : null;
    if (iid == null) {
      throw StateError(
        'gitlab_create_issue returned no issue iid: '
        '${raw == null ? 'tool not dispatchable' : trackerErrorOf(raw)}',
      );
    }
    return '$trimmedProject#$iid';
  }

  /// Dispatches [tool] with the resolved composite `key` and [extraArgs].
  void _dispatchKeyed(
    String key,
    String tool,
    Map<String, dynamic> extraArgs,
  ) {
    final ref = resolveIssueRef(key);
    if (ref == null) {
      throw StateError(
        "Cannot parse GitLab issue key: '$key'. Expected "
        "'namespace/project#123', 'gl-123', or a bare issue IID with the "
        'default project configured.',
      );
    }
    final (projectPath, iid) = ref;
    final raw = _execute(tool, {'key': '$projectPath#$iid', ...extraArgs});
    final error = raw == null
        ? '$tool is not dispatchable in this runtime'
        : trackerErrorOf(raw);
    if (error != null) throw StateError(error);
  }

  /// Resolves [key] to `(projectPath, iid)`:
  /// `namespace/project#42` verbatim; `gl-42` (any case) and bare `42`
  /// against `CI_PROJECT_PATH`, then `GITLAB_WORKSPACE` +
  /// `GITLAB_REPOSITORY`. `null` when anything is missing.
  GitlabTrackerIssueRef? resolveIssueRef(String key) {
    final trimmed = key.trim();
    final composite = _parseCompositeIssueRef(trimmed);
    if (composite != null) return composite;
    final bare = RegExp(r'^(?:gl-)?(\d+)$', caseSensitive: false)
        .firstMatch(trimmed)
        ?.group(1);
    if (bare == null) return null;
    final defaultProj = _defaultProjectPath();
    return defaultProj == null ? null : (defaultProj, bare);
  }

  static GitlabTrackerIssueRef? _parseCompositeIssueRef(String trimmed) {
    final sep = trimmed.lastIndexOf('#');
    if (sep <= 0 || sep >= trimmed.length - 1) return null;
    final iid = trimmed.substring(sep + 1);
    if (!RegExp(r'^\d+$').hasMatch(iid)) return null;
    final proj = trimmed.substring(0, sep).trim();
    final validProj =
        proj.contains('/') && proj.split('/').every((p) => p.trim().isNotEmpty);
    return validProj ? (proj, iid) : null;
  }

  static String? _defaultProjectPath() => resolveConfiguredGitlabProjectPath();
}

/// Resolves the configured default GitLab project path (`CI_PROJECT_PATH`,
/// then `GITLAB_WORKSPACE` + `GITLAB_REPOSITORY`), or `null` when absent.
String? resolveConfiguredGitlabProjectPath([PropertyReader? customReader]) {
  final reader = customReader ?? PropertyReader();
  final ciPath = (reader.getValue('CI_PROJECT_PATH') ?? '').trim();
  if (ciPath.contains('/')) return ciPath;
  final ws = reader.getGitLabWorkspace()?.trim() ?? '';
  final rp = reader.getGitLabRepository()?.trim() ?? '';
  return (ws.isNotEmpty && rp.isNotEmpty) ? '$ws/$rp' : null;
}

/// Issue-tracker sync executors — Java `GitLabIssues.java` (dm.ai #876).
///
/// Part of the `gitlab_sync_tools.dart` library so the handlers share the
/// sync config/HTTP helpers. Every issue tool resolves its reference from
/// explicit parts (`workspace`/`repository`/`issueNumber`, or the legacy
/// `project`/`iid` pair), a composite `key` (`namespace/project#123`,
/// `gl-123`, or a bare IID), or the configured `CI_PROJECT_PATH` /
/// `GITLAB_WORKSPACE` + `GITLAB_REPOSITORY` defaults — Java
/// `GitLabIssues.resolveIssueRef` parity.
part of 'gitlab_sync_tools.dart';

/// A resolved GitLab issue reference for one sync call.
class _GlSyncIssueRef {
  final String projectPath;
  final String iid;
  const _GlSyncIssueRef(this.projectPath, this.iid);

  /// `projects/<encoded>/issues/<iid>` API path segment.
  String get issueSeg =>
      'projects/${Uri.encodeComponent(projectPath)}/issues/$iid';
}

/// `gl-123` router key convention.
final RegExp _syncGlRouterKey = RegExp(r'^gl-(\d+)$', caseSensitive: false);

/// Bare numeric IID pattern.
final RegExp _syncGlBareDigits = RegExp(r'^\d+$');

/// Statuses that close a GitLab issue (Java parity).
const _syncGlClosedStatuses = {'done', 'closed', 'completed', 'resolved'};

/// Statuses that reopen a GitLab issue (Java parity).
const _syncGlOpenStatuses = {'open', 'opened', 'reopen', 'reopened'};

/// Parsed composite/partial GitLab sync key parts.
typedef _GlSyncKeyParts = ({String projectPath, String iid});

/// Resolves the GitLab issue reference from tool [args] (Java
/// `GitLabIssues.resolveIssueRef`). Returns a JSON error string when
/// unresolved.
Object _resolveGlSyncIssueRef(Map<String, dynamic> args) {
  final initialProj = _glExplicitProject(args);
  final initialIid = _glFirstStr(
    args,
    const ['issueNumber', 'number', 'iid', 'pullRequestId'],
  );
  final key = syncAsStr(args['key']).trim();
  final parsed = _parseGlSyncIssueKey(key);
  if (key.isNotEmpty && parsed == null) {
    return syncErr(
      "Cannot parse GitLab issue key: '$key'. Expected "
      "'namespace/project#123', 'gl-123', or a bare issue IID.",
    );
  }
  final projFromKey =
      initialProj.isNotEmpty ? initialProj : (parsed?.projectPath ?? '');
  final finalProj =
      projFromKey.isNotEmpty ? projFromKey : _glConfiguredProjectPath();
  final finalIid = initialIid.isNotEmpty ? initialIid : (parsed?.iid ?? '');
  if (finalProj.isEmpty || finalIid.isEmpty) {
    return syncErr(
      'GitLab issue reference requires workspace/repository/issueNumber '
      "or a composite key 'namespace/project#123' (or 'gl-123' with a "
      'configured default project).',
    );
  }
  return _GlSyncIssueRef(finalProj, finalIid);
}

String _glExplicitProject(Map<String, dynamic> args) {
  final direct = _glFirstStr(args, const ['project']);
  if (direct.isNotEmpty) return direct;
  final ws = _glFirstStr(args, const ['workspace', 'owner']);
  final rp = _glFirstStr(args, const ['repository', 'repo']);
  return (ws.isNotEmpty && rp.isNotEmpty) ? '$ws/$rp' : '';
}

String _glConfiguredProjectPath() {
  final r = PropertyReader();
  final ci = syncAsStr(r.getValue('CI_PROJECT_PATH')).trim();
  if (ci.contains('/')) return ci;
  final w = (r.getGitLabWorkspace() ?? '').trim();
  final p = (r.getGitLabRepository() ?? '').trim();
  return (w.isNotEmpty && p.isNotEmpty) ? '$w/$p' : '';
}

/// Parses composite `namespace/project#123`, `gl-123`, or bare IID [key].
_GlSyncKeyParts? _parseGlSyncIssueKey(String key) {
  if (key.isEmpty) return (projectPath: '', iid: '');
  final sep = key.lastIndexOf('#');
  if (sep > 0 &&
      sep < key.length - 1 &&
      _syncGlBareDigits.hasMatch(key.substring(sep + 1))) {
    return (
      projectPath: key.substring(0, sep),
      iid: key.substring(sep + 1),
    );
  }
  final router = _syncGlRouterKey.firstMatch(key)?.group(1);
  if (router != null) return (projectPath: '', iid: router);
  if (_syncGlBareDigits.hasMatch(key)) return (projectPath: '', iid: key);
  return null;
}

/// Resolves a GitLab project path from `workspace`/`repository`, `project`,
/// `key`, or configured defaults. Returns `null` when unresolved.
String? _resolveGlSyncProjectPath(Map<String, dynamic> args) {
  final key = syncAsStr(args['key']).trim();
  if (key.contains('/')) return key;
  final explicit = _glExplicitProject(args);
  if (explicit.isNotEmpty) return explicit;
  final configured = _glConfiguredProjectPath();
  return configured.isNotEmpty ? configured : null;
}

/// Runs [fn] with the resolved GitLab issue reference, or returns the JSON
/// error string.
String _withGlIssueRef(
  _GitlabConfig config,
  Map<String, dynamic> args,
  String Function(_GitlabConfig, _GlSyncIssueRef) fn,
) {
  final resolved = _resolveGlSyncIssueRef(args);
  return resolved is _GlSyncIssueRef
      ? fn(config, resolved)
      : resolved as String;
}

/// First non-blank string among [names] in [args].
String _glFirstStr(Map<String, dynamic> args, List<String> names) =>
    syncFirstStr(args, names);

String _putIssueJson(_GitlabConfig c, String url, Map<String, dynamic> body) =>
    syncStrictBodyOrError(
      SyncHttpClient.put(url, headers: c.headers, body: jsonEncode(body)),
    );

/// `gitlab_get_issue` — GET `projects/{id}/issues/{iid}`.
String _getIssue(_GitlabConfig c, Map<String, dynamic> a) => _withGlIssueRef(
      c,
      a,
      (c, ref) => syncStrictBodyOrError(
        SyncHttpClient.get('${c.baseUrl}/${ref.issueSeg}', headers: c.headers),
      ),
    );

/// `gitlab_search_issues` — GET `projects/{id}/issues?state=…&search=…`.
String _searchIssues(_GitlabConfig c, Map<String, dynamic> a) {
  final projectPath = _resolveGlSyncProjectPath(a);
  if (projectPath == null) {
    return syncErr(
      'GitLab project is not configured. Pass workspace/repository '
      'or set GITLAB_WORKSPACE and GITLAB_REPOSITORY.',
    );
  }
  final rawState = syncAsStr(a['state']).trim();
  final state = rawState.isEmpty ? 'all' : rawState;
  final query = syncAsStr(a['query']);
  final url = '${c.baseUrl}/projects/${Uri.encodeComponent(projectPath)}/issues'
      '?state=${Uri.encodeQueryComponent(state)}'
      '&per_page=100'
      '&search=${Uri.encodeQueryComponent(query)}';
  return syncStrictBodyOrError(SyncHttpClient.get(url, headers: c.headers));
}

/// `gitlab_create_issue` — POST `projects/{id}/issues`.
String _createIssue(_GitlabConfig c, Map<String, dynamic> a) {
  final projectPath = _resolveGlSyncProjectPath(a);
  if (projectPath == null) {
    return syncErr(
      'GitLab project is not configured. Pass workspace/repository '
      'or set GITLAB_WORKSPACE and GITLAB_REPOSITORY.',
    );
  }
  final payload = <String, dynamic>{'title': syncAsStr(a['title'])};
  final desc = _glFirstStr(a, const ['body', 'description']);
  if (desc.isNotEmpty) payload['description'] = desc;
  return syncStrictBodyOrError(
    SyncHttpClient.post(
      '${c.baseUrl}/projects/${Uri.encodeComponent(projectPath)}/issues',
      headers: c.headers,
      body: jsonEncode(payload),
    ),
  );
}

/// `gitlab_close_issue` — PUT `state_event=close`.
String _closeIssue(_GitlabConfig c, Map<String, dynamic> a) => _withGlIssueRef(
      c,
      a,
      (c, ref) => _putIssueJson(
        c,
        '${c.baseUrl}/${ref.issueSeg}',
        const {'state_event': 'close'},
      ),
    );

/// `gitlab_reopen_issue` — PUT `state_event=reopen`.
String _reopenIssue(_GitlabConfig c, Map<String, dynamic> a) => _withGlIssueRef(
      c,
      a,
      (c, ref) => _putIssueJson(
        c,
        '${c.baseUrl}/${ref.issueSeg}',
        const {'state_event': 'reopen'},
      ),
    );

/// `gitlab_move_issue_to_status` — close/reopen/scoped-label semantics.
String _moveIssueToStatus(_GitlabConfig c, Map<String, dynamic> a) {
  final status = syncAsStr(a['statusName']).trim();
  if (status.isEmpty) return syncErr('statusName is required');
  final resolved = _resolveGlSyncIssueRef(a);
  if (resolved is! _GlSyncIssueRef) return resolved as String;
  final lower = status.toLowerCase();
  final payload = _syncGlClosedStatuses.contains(lower)
      ? const <String, dynamic>{'state_event': 'close'}
      : _syncGlOpenStatuses.contains(lower)
          ? const <String, dynamic>{'state_event': 'reopen'}
          : <String, dynamic>{'add_labels': 'status::$status'};
  return _putIssueJson(c, '${c.baseUrl}/${resolved.issueSeg}', payload);
}

/// `gitlab_assign_issue` — looks up user via `/users?username=…`, then PUTs
/// `assignee_ids`.
String _assignIssue(_GitlabConfig c, Map<String, dynamic> a) {
  final user = syncAsStr(a['user']).trim();
  if (user.isEmpty) return syncErr('GitLab username must not be empty');
  final resolved = _resolveGlSyncIssueRef(a);
  if (resolved is! _GlSyncIssueRef) return resolved as String;
  final usersResp = SyncHttpClient.get(
    '${c.baseUrl}/users?username=${Uri.encodeQueryComponent(user)}',
    headers: c.headers,
  );
  if (!usersResp.isOk) return syncStrictBodyOrError(usersResp);
  final users = syncTryDecode(usersResp.body);
  if (users is! List || users.isEmpty || users.first is! Map) {
    return syncErr('GitLab user not found: $user');
  }
  final userId = (users.first as Map)['id'];
  return _putIssueJson(c, '${c.baseUrl}/${resolved.issueSeg}', {
    'assignee_ids': [userId],
  });
}

/// `gitlab_add_issue_label` — PUT `add_labels` on the issue.
String _addIssueLabel(_GitlabConfig c, Map<String, dynamic> a) =>
    _withGlIssueRef(
      c,
      a,
      (c, ref) => _putIssueJson(
        c,
        '${c.baseUrl}/${ref.issueSeg}',
        {'add_labels': syncAsStr(a['label'])},
      ),
    );

/// `gitlab_remove_issue_label` — PUT `remove_labels` on the issue.
String _removeIssueLabel(_GitlabConfig c, Map<String, dynamic> a) =>
    _withGlIssueRef(
      c,
      a,
      (c, ref) => _putIssueJson(
        c,
        '${c.baseUrl}/${ref.issueSeg}',
        {'remove_labels': syncAsStr(a['label'])},
      ),
    );

/// `gitlab_create_issue_comment` — POST `{body}` to `…/issues/{iid}/notes`.
String _createIssueComment(_GitlabConfig c, Map<String, dynamic> a) =>
    _withGlIssueRef(
      c,
      a,
      (c, ref) => syncStrictBodyOrError(
        SyncHttpClient.post(
          '${c.baseUrl}/${ref.issueSeg}/notes',
          headers: c.headers,
          body: jsonEncode({
            'body': _glFirstStr(a, const ['body', 'text', 'comment']),
          }),
        ),
      ),
    );

/// `gitlab_get_issue_comments` — paginated GET `…/issues/{iid}/notes?sort=asc`
/// (Java `GitLabIssues.getIssueComments` parity).
String _getIssueComments(_GitlabConfig c, Map<String, dynamic> a) =>
    _withGlIssueRef(c, a, _fetchAllIssueComments);

String _fetchAllIssueComments(_GitlabConfig c, _GlSyncIssueRef ref) {
  final all = <dynamic>[];
  var page = 1;
  while (true) {
    final resp = SyncHttpClient.get(
      '${c.baseUrl}/${ref.issueSeg}/notes?sort=asc&per_page=100&page=$page',
      headers: c.headers,
    );
    if (!resp.isOk) return syncStrictBodyOrError(resp);
    final decoded = syncTryDecode(resp.body);
    if (decoded is! List) return resp.body;
    all.addAll(decoded);
    if (decoded.length < 100) return jsonEncode(all);
    page++;
  }
}

/// Teammate job — Dart port of Java `Teammate` (`teammate/Teammate.java`),
/// ticket-driven mode only: the job selects tickets by `inputJql`, prepares
/// the `input/<ticketKey>/` context folder, and delegates each ticket to
/// [CliAgent] under the hood.
///
/// Scope note (port decision): Java Teammate's internal AI-processing branch
/// (`ContextOrchestrator` + `RequestDecompositionAgent` + LLM providers) is
/// intentionally not ported — the dmtools-agents Teammate configs run with
/// `skipAIProcessing: true` and let the CLI agent do the AI work via
/// `cliCommands`. Everything the configs actually use is ported:
/// ticket selection, the CI-run trace comment, and the full CliAgent
/// lifecycle (preJSAction → input folder → preCliJSAction → cliCommands →
/// postJSAction → reset).
library;

import '../config/property_reader.dart';
import '../js/job_runner.dart';
import '../js/sync_tool_dispatcher.dart';
import 'dart:convert';
import 'dart:io';

import 'cli_agent.dart';
import 'github_ticket_source.dart';
import 'github_tracker_client.dart';
import 'gitlab_ticket_source.dart';
import 'gitlab_tracker_client.dart';
import 'cli_agent_params.dart';
import 'input_context_config.dart';
import 'ticket_smart_sources.dart';
import 'tracker_selection.dart';

/// Fetches the hydrated tickets for [inputJql]: each ticket is a raw tracker
/// JSON map with at least `key` and `fields` (comments included).
typedef TeammateTicketSource = Future<List<Map<String, dynamic>>> Function(
    String inputJql);

/// Posts a trace/status comment to [key] (Jira comment parity).
typedef TeammateCommentPoster = Future<void> Function(String key, String body);

/// Ticket-driven Teammate job.
///
/// Runs one [CliAgent] per ticket resolved from `params.inputJql`:
/// - empty/missing `inputJql` → no-op success (Java: "skipping ticket
///   processing");
/// - each ticket becomes the [CliAgentParams] context id, so the input
///   folder is `input/<ticketKey>/`;
/// - `ciRunUrl` + enabled comments post the Java trace comment
///   (`[<agentId>] Processing started. CI Run: <url>`).
class TeammateJob {
  /// Creates the job from the raw `params` block of a Teammate config.
  ///
  /// - [ticketSource] — ticket lookup; defaults to the Jira sync tools
  ///   (search → get_ticket → get_comments hydration).
  /// - [commentPoster] — comment sink for the CI-run trace comment; defaults
  ///   to `jira_post_comment`.
  TeammateJob({
    required this.params,
    this.workingDirectory,
    this.ticketSource,
    this.commentPoster,
    this.propertyReader,
    this.jsRunner,
  });

  /// Raw params from the job config (the `params` block).
  final Map<String, dynamic> params;

  /// Working-directory override forwarded to each [CliAgent].
  final String? workingDirectory;

  /// Ticket lookup override (tests inject fakes; default: Jira sync tools).
  final TeammateTicketSource? ticketSource;

  /// Comment sink override (tests inject fakes; default: `jira_post_comment`).
  final TeammateCommentPoster? commentPoster;

  /// Property reader forwarded to each [CliAgent].
  final PropertyReader? propertyReader;

  /// JS runner forwarded to each [CliAgent].
  final JsJobRunner? jsRunner;

  /// Runs the job and returns `{'success': …, 'results': […]}` where each
  /// result item carries `ticket`, plus the [CliAgent] result fields.
  Future<Map<String, dynamic>> run() async {
    final inputConfig = InputContextConfig.fromJson(params);
    final inputJql =
        ((params['inputJql'] as String?) ?? inputConfig.jql ?? '').trim();
    if (inputJql.isEmpty) {
      final explicitKey = inputConfig.ticket;
      if (explicitKey != null && explicitKey.isNotEmpty) {
        final fetched = TicketSmartSources(propertyReader ?? PropertyReader())
            .fetchTicketByKey(explicitKey);
        return _runTickets([
          {'key': explicitKey, 'fields': <String, dynamic>{}, ...?fetched},
        ]);
      }
      final prepared = _preparedInputTicket();
      if (prepared == null) {
        return const {'success': true, 'results': []};
      }
      _consumePreparedInput();
      return _runSingle(prepared);
    }
    final source = _selectTicketSource(inputJql);
    final tickets = await source(inputJql);
    return _runTickets(tickets);
  }

  TeammateTicketSource _selectTicketSource(String inputJql) {
    final resolvedTracker =
        resolveTrackerType(propertyReader ?? PropertyReader());
    _sourceIsGitlab =
        looksLikeGitlabQuery(inputJql) || resolvedTracker == 'gitlab';
    _sourceIsGithub = !_sourceIsGitlab &&
        (looksLikeGithubQuery(inputJql) || resolvedTracker == 'github');
    if (ticketSource != null) return ticketSource!;
    if (_sourceIsGitlab) return gitlabIssueTicketSource;
    if (_sourceIsGithub) return githubIssueTicketSource;
    return jiraTicketSource;
  }

  /// Runs every resolved ticket through a loud [CliAgent], then applies
  /// the Java Teammate end-of-run hard stop (epam/dm.ai#580): all matched
  /// tickets are attempted, but if any `preCliJSAction` threw an uncaught
  /// exception the overall job fails so the CI step actually goes red.
  Future<Map<String, dynamic>> _runTickets(
      List<Map<String, dynamic>> tickets) async {
    final results = <Map<String, dynamic>>[];
    final unexpectedSetupFailures = <String>[];
    for (final ticket in tickets) {
      final outcome = await _runTicket(ticket);
      if (outcome.postJsError != null) {
        // #585 parity: Java's RuntimeException propagates out of
        // runJobImpl — the job fails immediately and the remaining
        // tickets are never attempted.
        results.add(outcome.result);
        return {
          'success': false,
          'error': outcome.postJsError,
          'results': results,
        };
      }
      if (outcome.key != null && outcome.setupThrew) {
        unexpectedSetupFailures.add(outcome.key!);
      }
      results.add(outcome.result);
    }
    if (unexpectedSetupFailures.isNotEmpty) {
      return {
        'success': false,
        'error': _abortMessage(unexpectedSetupFailures),
        'results': results,
      };
    }
    final ok = results.isNotEmpty && results.every((r) => r['success'] == true);
    return {'success': ok, 'results': results};
  }

  /// Runs one ticket: trace comment, then a loud [CliAgent] (Java
  /// Teammate epam/dm.ai#580/#585 parity — uncaught JS-action exceptions
  /// fail the job visibly instead of being swallowed into warnings).
  Future<_TicketOutcome> _runTicket(Map<String, dynamic> ticket) async {
    final key = _ticketKey(ticket);
    if (key == null || key.isEmpty) {
      return _TicketOutcome.resultOnly({
        'ticket': null,
        'success': false,
        'error': 'search result without a ticket key',
      });
    }
    await _postTraceComment(key);
    final agent = CliAgent(
      params: _paramsForTicket(key),
      workingDirectory: workingDirectory,
      ticketData: ticket,
      propertyReader: propertyReader,
      jsRunner: jsRunner,
      failOnJsActionErrors: true,
    );
    final result = await agent.run();
    if (_shouldPostCompletionComment(result)) {
      await _postCompletionComment(key);
    }
    return _TicketOutcome(
      key: key,
      result: {'ticket': key, 'success': result['success'] == true, ...result},
      setupThrew: result['unexpectedSetupFailure'] == true,
      postJsError: result['postJsActionUncaught'] == true
          ? result['error'] as String?
          : null,
    );
  }

  /// Runs one [CliAgent] against a single prepared [ticket] (no per-ticket
  /// contextId override and no Jira trace comment — there is no tracker).
  Future<Map<String, dynamic>> _runSingle(Map<String, dynamic> ticket) async {
    final agent = CliAgent(
      params: CliAgentParams.fromJson(params),
      workingDirectory: workingDirectory,
      ticketData: ticket,
      propertyReader: propertyReader,
      jsRunner: jsRunner,
      failOnJsActionErrors: true,
    );
    final result = await agent.run();
    final key = _ticketKey(ticket);
    if (result['postJsActionUncaught'] == true) {
      return {'success': false, 'error': result['error'], 'results': []};
    }
    if (result['unexpectedSetupFailure'] == true) {
      // Java Teammate #580 parity: a swallowed uncaught setup exception
      // fails the job — the CI step must go red.
      return {
        'success': false,
        'error': _abortMessage([key ?? 'unknown']),
        'results': [],
      };
    }
    return {
      'success': result['success'] == true,
      'results': [
        {'ticket': key, 'success': result['success'] == true, ...result}
      ],
    };
  }

  /// Java Teammate end-of-run hard-stop message (epam/dm.ai#580), listing
  /// every ticket whose `preCliJSAction` threw an uncaught exception.
  String _abortMessage(List<String> tickets) =>
      'Teammate job aborted: preCliJSAction threw an unexpected error '
      '(e.g. a git command failure) for ticket(s) $tickets — see the '
      'warnings logged above for the underlying error(s).';

  /// The caller-provided ticket at `<workDir>/input/ticket.md`, mapped to
  /// the raw-tracker shape [CliAgent] understands (first line → summary,
  /// the rest → description), or null when absent/blank.
  Map<String, dynamic>? _preparedInputTicket() {
    final base = workingDirectory ?? Directory.current.path;
    final file = File('$base/input/ticket.md');
    if (!file.existsSync()) return null;
    final content = file.readAsStringSync().trim();
    if (content.isEmpty) return null;
    final newline = content.indexOf('\n');
    final summary =
        newline < 0 ? content : content.substring(0, newline).trim();
    final description =
        newline < 0 ? '' : content.substring(newline + 1).trim();
    return {
      'key': _contextId(),
      'fields': {'summary': summary, 'description': description},
    };
  }

  /// Deletes the consumed bootstrap `input/ticket.md`.
  ///
  /// The ticket now lives in memory and the canonical `input/<contextId>/`
  /// context is built from it by [CliAgent]; the root copy must not
  /// survive the consumption — left in the tree it (a) duplicates the
  /// ticket body next to the canonical context and (b) leaks an
  /// uncommitted runtime file into the agent's git flow: the branch-setup
  /// stash pops it onto the tracked version with conflict markers that
  /// the agent's final `git add -A` then commits (seen on fa gh-671:
  /// `input/ticket.md` and `input/gh-671/ticket.md` both carried
  /// `<<<<<<< Updated upstream` blocks). Best-effort — a locked file
  /// must not fail the job.
  void _consumePreparedInput() {
    final base = workingDirectory ?? Directory.current.path;
    final file = File('$base/input/ticket.md');
    if (!file.existsSync()) return;
    try {
      file.deleteSync();
    } catch (_) {
      // Best-effort: never fail the job over cleanup.
    }
  }

  /// The config's `metadata.contextId`, falling back to CliAgent's own
  /// `'cli-agent'` default.
  String _contextId() {
    final md = params['metadata'];
    if (md is Map) {
      final contextId = md['contextId'];
      if (contextId is String && contextId.isNotEmpty) return contextId;
    }
    return 'cli-agent';
  }

  /// Per-ticket [CliAgentParams]: the shared config with `metadata.contextId`
  /// pinned to the ticket key (Java Teammate's input folder is
  /// `input/<ticketKey>/`).
  CliAgentParams _paramsForTicket(String key) {
    final p = CliAgentParams.fromJson(params);
    p.metadata = {...?p.metadata, 'contextId': key};
    return p;
  }

  /// Posts the CI-run trace comment when `ciRunUrl` is set and comments are
  /// enabled (`alwaysPostComments` or non-`none` `outputType`).
  ///
  /// The default sink follows the ticket source: GitHub-sourced tickets
  /// post through [GithubTrackerClient] (Java `trackerClient.postComment`
  /// with `DEFAULT_TRACKER=github`), everything else through
  /// `jira_post_comment`. A failed trace comment never fails the job —
  /// Java catches, warns, and continues.
  Future<void> _postTraceComment(String key) =>
      _postCiRunComment(key, (url) => 'Processing started. CI Run: $url');

  /// Posts the completion comment when `ciRunUrl` is set, `initiator` is
  /// provided, and comments are enabled (Java `Teammate.postCompletionComment`
  /// parity).
  Future<void> _postCompletionComment(String key) =>
      _postCiRunComment(key, _buildCompletionComment);

  /// Shared advisory CI-run comment poster: swallows poster failures so trace/
  /// completion comments never abort ticket processing (Java parity).
  Future<void> _postCiRunComment(
      String key, String Function(String ciRunUrl) bodyBuilder) async {
    final ciRunUrl = (params['ciRunUrl'] as String?)?.trim() ?? '';
    if (ciRunUrl.isEmpty || !_shouldPostComments) return;
    final poster = commentPoster ??
        (_sourceIsGitlab
            ? _gitlabCommentPoster
            : (_sourceIsGithub ? _githubCommentPoster : _jiraCommentPoster));
    try {
      await poster(key, '${_agentNamePrefix()}${bodyBuilder(ciRunUrl)}');
    } catch (_) {
      // Advisory comment only — processing continues (Java parity).
    }
  }

  /// Whether [result] reached the end of `Teammate.runJobImpl` where Java
  /// calls `postCompletionComment` with a non-empty `initiator`: skipped
  /// tickets (`preJSAction` returned `false` or `preCliJSAction` failed/threw)
  /// and uncaught `postJSAction` exceptions exit before completion notification,
  /// and runs without `initiator` rely on `postJSAction` for completion updates.
  bool _shouldPostCompletionComment(Map<String, dynamic> result) {
    final initiator = (params['initiator'] as String?)?.trim() ?? '';
    if (initiator.isEmpty) return false;
    if (result['success'] != true) return false;
    if (result['unexpectedSetupFailure'] == true) return false;
    final response = result['response'];
    return response != 'Skipped by pre-action' &&
        response != 'Skipped: preCliJSAction reported failure';
  }

  /// Java `Teammate.buildCompletionComment`: tags the initiator when non-empty.
  String _buildCompletionComment(String ciRunUrl) {
    final initiator = (params['initiator'] as String?)?.trim() ?? '';
    if (initiator.isNotEmpty) {
      return '${_tagInitiator(initiator)}, \n\n✅ Teammate run completed. CI Run: $ciRunUrl';
    }
    return '✅ Teammate run completed. CI Run: $ciRunUrl';
  }

  /// Java `TrackerClient.tag(initiator)`: Jira wraps account IDs in
  /// `[~accountid:...]` (or `[...]` if `~` is already present); GitHub returns
  /// the initiator verbatim.
  String _tagInitiator(String initiator) {
    if (_sourceIsGithub || _sourceIsGitlab) return initiator;
    if (initiator.contains('~')) {
      return initiator.startsWith('[') && initiator.endsWith(']')
          ? initiator
          : '[$initiator]';
    }
    return '[~accountid:$initiator]';
  }

  /// Java `AbstractJob.shouldPostComments`: `alwaysPostComments` wins, else
  /// comments are on when `outputType` is not `none`.
  bool get _shouldPostComments {
    if (params['alwaysPostComments'] == true) return true;
    final outputType = (params['outputType'] as String?)?.trim().toLowerCase();
    return outputType != null && outputType.isNotEmpty && outputType != 'none';
  }

  /// Whether the resolved ticket source is the GitHub-issues one — trace
